		["Patch Notes"] = {
			{ Text = "<b>Non-Card Changes</b><br /><br /><i></i>" },
			{
				Text = "<b>Auctions have returned!</b><br />Auctions have returned to BC in a new (old) form! Players will now be able to bid against eachother for epic and legendary cards!<br /><i></i>"
			},
			{
				Text = "<b>History Core Compensation</b><br />All players who have played and won a game in the past 6 months will recieve 9 history cores so they can have all the packs they originally had unlocked available.<br /><i></i>"
			},
			{
				Text = "<b>Card Changes</b><br />Followup Balance Changes<br /><i></i>"
			},
			{
				Text = "<b>One Against All</b><br />No longer draws a card.<br /><i>In the process of attempting to rebalance 2v1 duels, we overcorrected slightly on adjusting the power back to the solo player, where fighting them outside of a optimized team deck would always result in a unwinnable situation. This change also resolves issues with some mill focused team decks making the opposite case happen.</i>"
			},
			{
				Text = "<b>Wall Dweller</b><br />Now drains 150 life (from 300) per trigger.<br /><i>The previous nerf was intended to half the amount of lifeloss wall dwellers inflicted per turn cycle based off what it was doing on release, but we forgot to account for the fact that the opponent's 4-cost triggers was not working until then, this change corrects it so the total amount lost is reduced to what was intended initially.</i>"
			},
			{
				Text = "<b>zachattack83</b><br />No longer Generates on Lifeloss<br /><i>Refer to Myrmiredon's Card Design notes 17.</i>"
			},
			{
				Text = "<b>Descend Down Kralosa</b><br />Now unranked.\nEffect now \"Twice each turn, whenever you cast a Colourless card: Attach a gear to this card and a target fighter gains 150 health. During your end step, if 6 gears are on this card: Destroy them all, then return all fighters and terrain to their hand. Allied returned fighters gain 300 health, haste, and overload.\"<br /><i></i>"
			}
		}
