		Date = "March 27th 2026",
		Card = "Dubious Receptionists",
		["Patch Notes"] = {
			{
				Text = "<b>New Group: Dubious</b><br />A BY Group focused on Unleashing and defending your train! Check it out in the shop!<br /><i></i>"
			},
			{
				Text = "<b>Balance Changes</b><br /><br /><i>These are some small follow-up changes to address things we missed or didn't correctly change in the last large balance patch.</i>"
			},
			{
				Text = "<b>The Master Acolyte</b><br />Now triggers only when an unranked fighter is cast. Now only triggers thrice each turn.<br /><i>Okay fair enough, I wasn't expecting the strategy where you don't play acolytes in your acolyte deck. Simply capping it won't do much due to division effects, so we've also forced you to play unranked acolytes en masse to get the incredible bonus this card affords, which also brings the card in line with how we tested it. Well done, you got me.</i>"
			},
			{
				Text = "<b>Cursed Technique Reversal: Green</b><br />Can no longer remove the last {R}{G}{B}{Y} in the card's cost.<br /><i>This is a token from Xi_nal, The Honoured One.</i>"
			},
			{
				Text = "<b>Kahgo</b><br />Now 100/200 (+50/+150), no longer has haste.<br /><i>Comedy over</i>"
			},
			{
				Text = "<b>Django Haplorhini</b><br />Now also triggers off of discarding Elements.<br /><i></i>"
			},
			{
				Text = "<b>Milk, Vivere</b><br />No longer converts the cost of cards to colourless.<br /><i>Temporary change to address explosive usage of this card converting boardwipes and tricolor rares into being easily playable</i>"
			},
			{
				Text = "<b>The Forgotten One</b><br />Reverted immunities back to only Depower, Damage, Set, Return and Destroy. (From immune to all effects)<br /><i>Remenant possible compensation buff from the titan of the holy chamber change that we forgot to revert</i>"
