			},
			{
				Text = "<b>DIY Dominus</b><br />Now swaps all allied fighters (from all green fighters)<br /><i>You are unleashing an ancient curse by doing this. Good thing we're nerfing titan stones this patch too, huh.</i>"
			},
			{
				Text = "<b>John Deathedge</b><br />Now 250/400 (+200/+0)<br /><i></i>"
			},
			{
				Text = "<b>Revenants</b><br />Now 150/300 (+100/0)<br /><i>This is the token summoned from Freddyland Utility Tunnels.</i>"
